local GlassLehrBeltMaker = {}
local PRODUCTS = {
    iron_glasslehrbelt = { name = "Železni trak za ohlajevalne peči", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni trak za ohlajevalne peči za steklarje." },
    bronze_glasslehrbelt = { name = "Bronast trak za ohlajevalne peči", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast trak za ohlajevalne peči za steklarje." },
    silver_glasslehrbelt = { name = "Srebrn trak za ohlajevalne peči", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn trak za ohlajevalne peči za steklarje." },
    gilded_glasslehrbelt = { name = "Pozlačen trak za ohlajevalne peči", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen trak za ohlajevalne peči za steklarje." },
    jewel_set_glasslehrbelt = { name = "Draguljast trak za ohlajevalne peči", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast trak za ohlajevalne peči za steklarje." },
    royal_sovereign_glasslehrbelt = { name = "Kraljevski suveren trak za ohlajevalne peči", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren trak za ohlajevalne peči z biseri za krono." },
}
